# Treści kursu biologii — porcja 7: Rośliny (przegląd, tkanki, organy, gospodarka wodna).
T = {}

T['b-przeglad-roslin'] = dict(F=[
 ('Wyjaśnij pojęcie: zielenice', 'Glony (rośliny pierwotnie wodne) z chlorofilem a i b, magazynujące skrobię w chloroplastach i mające celulozową ścianę — przodkowie roślin lądowych (np. chlorella, skrętnica, ramienice).'),
 ('Wyjaśnij pojęcie: krasnorosty', 'Glony głównie morskie z chlorofilem a i fikobilinami (czerwona barwa), magazynujące skrobię krasnorostową w cytoplazmie; brak wici w cyklu (np. Porphyra — nori).'),
 ('Jak odróżnić krasnorosty od zielenic?', 'Krasnorosty: fikobiliny (czerwona barwa), skrobia krasnorostowa w cytoplazmie, brak stadiów z wiciami; zielenice: chlorofil a i b, skrobia w chloroplastach, często stadia z wiciami.'),
 ('Znaczenie krasnorostów dla człowieka', 'Źródło agaru (podłoża mikrobiologiczne, żelujący dodatek E406) i karagenu; pokarm (nori w sushi).'),
 ('Znaczenie zielenic w przyrodzie i dla człowieka', 'Producenci w wodach (fitoplankton), źródło tlenu; chlorella — suplementy; organizmy modelowe i potencjalne źródło biopaliw.'),
 ('Różnice między warunkami życia w wodzie i na lądzie', 'Na lądzie: ryzyko wysychania, brak wyporu (potrzebne tkanki wzmacniające), więcej światła i CO₂, większe wahania temperatury, rozmnażanie bez wody (problem dla gamet).'),
 ('Przystosowania roślin do życia na lądzie', 'Skórka z kutykulą i szparkami, tkanki przewodzące i wzmacniające, korzenie, ochrona gamet i zarodków (rodnie, plemnie, nasiona), zarodniki ze sporopoleniną.'),
 ('Cechy mchów', 'Brak tkanek przewodzących i prawdziwych korzeni (chwytniki); dominuje gametofit; do zapłodnienia potrzebna woda; sporofit (puszka z setą) rozwija się na gametoficie.'),
 ('Cechy widłakowych', 'Rośliny naczyniowe zarodnikowe z drobnymi, gęsto ułożonymi liśćmi (mikrofilami); zarodnie w kłosach zarodnionośnych; dominuje sporofit; np. widłak goździsty.'),
 ('Cechy skrzypowych', 'Rośliny zarodnikowe z łodygami członowanymi, inkrustowanymi krzemionką, z liśćmi zredukowanymi do okółków ząbków; kłos zarodnionośny na szczycie pędu; np. skrzyp polny (pędy zarodnionośne wiosną).'),
 ('Cechy paprociowych', 'Rośliny naczyniowe zarodnikowe z dużymi, pierzastymi liśćmi (często zwiniętymi pastorałowato w młodości); zarodnie w kupkach na spodzie liści; dominuje sporofit; gametofit — przedrośle.'),
 ('Cechy roślin nasiennych', 'Wytwarzają nasiona; zapłodnienie niezależne od wody (łagiewka pyłkowa); silnie zredukowany gametofit; nagonasienne (zalążki na łuskach) i okrytonasienne (zalążki w zalążni, kwiaty, owoce).'),
 ('Czym różnią się nagonasienne od okrytonasiennych?', 'Nagonasienne: zalążki leżą odkryte na łuskach nasiennych, brak owoców i kwiatów właściwych, w drewnie głównie cewki. Okrytonasienne: zalążki w zalążni słupka, powstaje owoc, w drewnie naczynia, podwójne zapłodnienie.'),
 ('Rodzime przykłady nagonasiennych', 'Sosna zwyczajna, świerk pospolity, jodła, modrzew, jałowiec, cis (pod ochroną).'),
 ('Jak rozpoznać mech na zdjęciu?', 'Niska, zielona darń listkowatych łodyżek bez kwiatów; nad nią ulistnione sporofity: seta z puszką zarodni (u płonnika, torfowca).'),
 ('Jak rozpoznać paproć na zdjęciu?', 'Duże, podzielone liście bez kwiatów; na spodzie liści brązowe kupki zarodni; młode liście zwinięte jak pastorał.'),
 ('Znaczenie mchów torfowców', 'Tworzą torfowiska — magazynują wodę i węgiel (torf), kształtują stosunki wodne; zakwaszają środowisko.'),
 ('Wyjaśnij pojęcie: rośliny naczyniowe', 'Rośliny mające tkanki przewodzące (drewno i łyko): widłakowe, skrzypowe, paprociowe i nasienne.'),
 ('Wyjaśnij pojęcie: przedrośle', 'Gametofit paproci — mała, sercowata, zielona płytka z rodniami i plemniami, rozwijająca się z zarodnika.'),
 ('Znaczenie roślin dla człowieka', 'Pokarm, pasza, surowce (drewno, włókna, oleje), leki, przyprawy, rośliny ozdobne, tlen i klimat, ochrona gleby.'),
 ('Wyjaśnij pojęcie: rośliny wtórnie wodne', 'Rośliny lądowe (np. grzybień, moczarka, rdestnica), które wtórnie przystosowały się do życia w wodzie — mają np. przestwory powietrzne (aerenchymę), zredukowane tkanki wzmacniające.'),
 ('Dlaczego mchy osiągają niewielkie rozmiary?', 'Nie mają tkanek przewodzących i wzmacniających — woda przemieszcza się wolno komórka po komórce, a ciało nie mogłoby się utrzymać bez podpory.'),
 ('Wyjaśnij pojęcie: zarodnik (spora)', 'Haploidalna komórka rozrodcza powstała przez mejozę w zarodni sporofitu; daje początek gametoficie.'),
 ('Porównanie dominującego pokolenia w grupach roślin', 'Mchy — gametofit; widłakowe, skrzypowe, paprociowe, nasienne — sporofit (u nasiennych gametofit silnie zredukowany).'),
 ('Wyjaśnij pojęcie: różnozarodnikowość', 'Wytwarzanie dwóch rodzajów zarodników: mikrospor (dają gametofity męskie) i makrospor (gametofity żeńskie) — u niektórych widłakowych, paproci wodnych i wszystkich roślin nasiennych.'),
 ('Jak rozpoznać roślinę jednoliścienną?', 'Równoległe unerwienie liści, wiązkowy system korzeniowy, rozproszone wiązki w łodydze, kwiaty trójkrotne, jeden liścień (np. trawy, lilie, storczyki).'),
 ('Jak rozpoznać roślinę dwuliścienną?', 'Siateczkowate unerwienie, system palowy, wiązki ułożone w pierścień, kwiaty cztero- lub pięciokrotne, dwa liścienie (np. fasola, róża, dąb).'),
 ('Wyjaśnij pojęcie: porosty (powiązanie z roślinami)', 'Nie są roślinami — to symbioza grzyba z glonem lub sinicą; omawiane w dziale grzybów.'),
 ('Gatunki chronione wśród paprotników i mchów — przykłady', 'Widłaki (np. widłak goździsty — częściowo), długosz królewski, pióropusznik strusi, torfowce (częściowo).'),
 ('Wyjaśnij pojęcie: sporofit', 'Diploidalne pokolenie rośliny wytwarzające zarodniki w zarodniach (przez mejozę).'),
], Q=[
 ('Fikobiliny jako barwniki pomocnicze mają:', ['zielenice', '*krasnorosty', 'mchy', 'paprocie'], 'Czerwona barwa krasnorostów.'),
 ('Dominującym pokoleniem u mchów jest:', ['sporofit', '*gametofit', 'przedrośle', 'zarodnik'], 'Zielona darń to gametofity.'),
 ('Zalążki leżące odkryte na łuskach to cecha:', ['okrytonasiennych', '*nagonasiennych', 'paproci', 'mchów'], 'Nagonasienne.'),
 ('Agar pozyskuje się z:', ['zielenic', '*krasnorostów', 'okrzemek', 'brunatnic'], 'Krasnorosty.'),
 ('Łodygi członowane z krzemionką i okółkami ząbkowatych liści ma:', ['widłak', '*skrzyp', 'paproć orlica', 'mech płonnik'], 'Skrzypowe.'),
 ('Cechą rośliny jednoliściennej jest:', ['palowy system korzeniowy', '*równoległe unerwienie liści', 'pierścieniowy układ wiązek', 'kwiaty pięciokrotne'], 'Np. trawy.'),
], pp='IX')

T['b-tkanki-roslinne'] = dict(F=[
 ('Wyjaśnij pojęcie: tkanka', 'Zespół komórek o podobnej budowie i pochodzeniu, pełniących wspólną funkcję.'),
 ('Wyjaśnij pojęcie: merystemy (tkanki twórcze)', 'Tkanki zbudowane z małych, żywych komórek z dużym jądrem, gęstą cytoplazmą i cienką ścianą, zdolnych do podziałów — wytwarzają nowe komórki.'),
 ('Wyjaśnij pojęcie: merystemy wierzchołkowe', 'Merystemy pierwotne w stożkach wzrostu pędu i korzenia — odpowiadają za wzrost na długość.'),
 ('Wyjaśnij pojęcie: kambium (miazga)', 'Merystem boczny wtórny w łodydze i korzeniu roślin dwuliściennych i nagonasiennych — wytwarza do wewnątrz drewno wtórne, a na zewnątrz łyko wtórne (przyrost na grubość).'),
 ('Wyjaśnij pojęcie: fellogen (miazga korkotwórcza)', 'Merystem boczny wytwarzający na zewnątrz korek, a do wewnątrz fellodermę — tworzy perydermę zastępującą skórkę.'),
 ('Wyjaśnij pojęcie: merystemy interkalarne (wstawowe)', 'Merystemy u nasady międzywęźli (np. traw) — umożliwiają wzrost łodygi na długość także poza wierzchołkiem.'),
 ('Wyjaśnij pojęcie: tkanki stałe', 'Tkanki powstałe z merystemów, których komórki utraciły zdolność do podziałów i wyspecjalizowały się: okrywające, miękiszowe, wzmacniające, przewodzące, wydzielnicze.'),
 ('Wyjaśnij pojęcie: skórka (epiderma)', 'Jednowarstwowa tkanka okrywająca młode organy; komórki ściśle przylegające, zwykle bez chloroplastów (oprócz szparkowych), pokryte kutykulą; występują włoski i szparki.'),
 ('Wyjaśnij pojęcie: aparat szparkowy', 'Dwie komórki szparkowe (z chloroplastami, o nierównomiernie zgrubiałej ścianie) otaczające szparkę oraz komórki przyszparkowe — reguluje wymianę gazową i transpirację.'),
 ('Wyjaśnij pojęcie: kutykula', 'Warstwa kutyny i wosków na zewnętrznej ścianie komórek skórki — ogranicza parowanie wody i chroni przed patogenami.'),
 ('Wyjaśnij pojęcie: włośniki', 'Wypustki komórek skórki korzenia (ryzodermy) zwiększające powierzchnię pobierania wody i soli mineralnych.'),
 ('Wyjaśnij pojęcie: korek (felem)', 'Tkanka okrywająca wtórna z martwych komórek o ścianach przesyconych suberyną — nieprzepuszczalna dla wody i gazów, chroni pień i korzenie.'),
 ('Wyjaśnij pojęcie: przetchlinki', 'Miejsca w korku z luźno ułożonymi komórkami i przestworami — umożliwiają wymianę gazową (np. ciemne kreski na pniu brzozy).'),
 ('Wyjaśnij pojęcie: miękisz asymilacyjny', 'Tkanka z licznymi chloroplastami przeprowadzająca fotosyntezę — miękisz palisadowy (wydłużone komórki) i gąbczasty (z dużymi przestworami) w liściu.'),
 ('Wyjaśnij pojęcie: miękisz spichrzowy', 'Tkanka magazynująca substancje zapasowe (skrobia, białka, tłuszcze) — np. w bulwach, korzeniach spichrzowych, nasionach.'),
 ('Wyjaśnij pojęcie: miękisz wodonośny', 'Tkanka z dużymi wakuolami gromadzącymi wodę — u sukulentów (kaktusy, rozchodniki).'),
 ('Wyjaśnij pojęcie: miękisz powietrzny (aerenchyma)', 'Tkanka z dużymi przestworami międzykomórkowymi wypełnionymi powietrzem — u roślin wodnych i bagiennych; ułatwia dostęp tlenu do zanurzonych organów i utrzymuje je na powierzchni.'),
 ('Wyjaśnij pojęcie: kolenchyma (zwarcica)', 'Tkanka wzmacniająca z żywych komórek o nierównomiernie zgrubiałych, celulozowych ścianach — wzmacnia rosnące organy (np. ogonki liściowe, młode łodygi), nie hamując ich wzrostu.'),
 ('Wyjaśnij pojęcie: sklerenchyma (twardzica)', 'Tkanka wzmacniająca z martwych komórek o równomiernie zgrubiałych, zwykle zdrewniałych ścianach: włókna (np. len) i sklereidy (np. w łupinie orzecha, gruszce).'),
 ('Czym różni się kolenchyma od sklerenchymy?', 'Kolenchyma — żywe komórki, ściany celulozowe zgrubiałe nierównomiernie, w organach rosnących; sklerenchyma — martwe komórki, ściany zdrewniałe, zgrubiałe równomiernie, w organach dojrzałych.'),
 ('Wyjaśnij pojęcie: drewno (ksylem)', 'Tkanka przewodząca wodę i sole mineralne od korzenia do liści; elementy przewodzące: naczynia i cewki (martwe, zdrewniałe); także włókna drzewne i miękisz drzewny.'),
 ('Wyjaśnij pojęcie: łyko (floem)', 'Tkanka przewodząca produkty fotosyntezy (sacharozę); elementy przewodzące: rurki sitowe z komórkami przyrurkowymi (żywe); także włókna łykowe i miękisz łykowy.'),
 ('Czym różnią się naczynia od cewek?', 'Naczynia — rurki z członów, których ściany poprzeczne zanikły (szybki przepływ), u okrytonasiennych; cewki — wydłużone komórki z zachowanymi ścianami poprzecznymi i jamkami, u nagonasiennych i paprotników.'),
 ('Budowa rurki sitowej a funkcja', 'Żywe komórki bez jądra, z cienką warstwą cytoplazmy, połączone płytami sitowymi z porami — umożliwiają przepływ soku; funkcje życiowe wspiera komórka przyrurkowa.'),
 ('Wyjaśnij pojęcie: komórka przyrurkowa', 'Komórka z jądrem i licznymi mitochondriami towarzysząca członowi rurki sitowej — dostarcza ATP i białek, uczestniczy w załadunku sacharozy.'),
 ('Budowa naczynia a funkcja', 'Martwe, puste rurki bez ścian poprzecznych, ze zdrewniałymi, zgrubiałymi ścianami (pierścieniowo, spiralnie, siateczkowato) — umożliwiają szybki przepływ wody i są odporne na zgniecenie.'),
 ('Wyjaśnij pojęcie: wiązka przewodząca', 'Zespół drewna i łyka (czasem z kambium i sklerenchymą) przebiegający przez łodygę, liście i korzeń.'),
 ('Typy wiązek przewodzących', 'Kolateralna zamknięta (bez kambium, jednoliścienne), kolateralna otwarta (z kambium, dwuliścienne), bikolateralna (łyko po obu stronach drewna, np. dyniowate), koncentryczne, promieniste (w korzeniu).'),
 ('Wyjaśnij pojęcie: tkanki wydzielnicze', 'Komórki lub zespoły komórek wydzielające substancje: włoski gruczołowe, miodniki (nektar), kanały żywiczne, rury mleczne (lateks), hydatody (woda).'),
 ('Wyjaśnij pojęcie: hydatody', 'Szparki wodne na brzegach liści, przez które wydzielana jest woda w postaci kropli (gutacja) przy wysokiej wilgotności powietrza.'),
 ('Wyjaśnij pojęcie: gutacja', 'Wydzielanie wody w postaci kropli przez hydatody, gdy transpiracja jest słaba, a parcie korzeniowe silne (np. rano na liściach traw).'),
 ('Jak rozpoznać na preparacie drewno?', 'Martwe komórki o grubych, zdrewniałych ścianach (barwią się floroglucyną na czerwono), z dużymi światłami naczyń, bez cytoplazmy.'),
 ('Jak rozpoznać na preparacie łyko?', 'Żywe komórki o cienkich ścianach: rurki sitowe z płytami sitowymi i mniejsze komórki przyrurkowe z jądrami.'),
 ('Wyjaśnij pojęcie: przestwory międzykomórkowe', 'Wolne przestrzenie między komórkami (wypełnione powietrzem) — umożliwiają dyfuzję gazów w tkankach.'),
 ('Wyjaśnij pojęcie: endoderma (śródskórnia)', 'Wewnętrzna warstwa kory korzenia z pasemkami Caspary’ego — kontroluje przechodzenie wody i jonów do walca osiowego.'),
 ('Wyjaśnij pojęcie: pasemka Caspary’ego', 'Pasma suberyny w ścianach komórek endodermy — blokują transport apoplastyczny, zmuszając wodę i jony do przejścia przez błony (selekcja).'),
 ('Wyjaśnij pojęcie: perycykl', 'Zewnętrzna warstwa walca osiowego korzenia, zdolna do podziałów — wytwarza korzenie boczne i (u dwuliściennych) uczestniczy w przyroście wtórnym.'),
 ('Połączenia międzykomórkowe w tkankach roślinnych', 'Plazmodesmy (cytoplazmatyczne kanaliki przez ściany) — transport symplastyczny substancji i sygnałów; blaszka środkowa — spaja komórki.'),
 ('Znaczenie plazmodesm w tkankach roślinnych', 'Umożliwiają przemieszczanie wody, jonów, cukrów, hormonów, RNA i białek między komórkami, koordynując funkcje tkanki.'),
 ('Jak przeprowadzić obserwację tkanki przewodzącej wodę?', 'Wstawić łodygę selera lub białego kwiatu do wody z barwnikiem (np. eozyną, tuszem) i po kilku godzinach obejrzeć przekrój — zabarwione są wiązki drewna.'),
 ('Wyjaśnij pojęcie: drewno wczesne i późne (słoje)', 'Drewno wczesne (wiosenne) — duże naczynia, cienkie ściany, jaśniejsze; późne (letnie) — mniejsze komórki, grubsze ściany, ciemniejsze; razem tworzą słój roczny.'),
 ('Jak określić wiek drzewa na przekroju pnia?', 'Policzyć przyrosty roczne (słoje) drewna — każdy odpowiada jednemu sezonowi wegetacyjnemu.'),
 ('Wyjaśnij pojęcie: twardziel', 'Wewnętrzna, ciemniejsza część pnia z martwym, nieprzewodzącym drewnem przesyconym garbnikami i żywicami — pełni funkcję mechaniczną.'),
 ('Wyjaśnij pojęcie: biel', 'Zewnętrzna, jaśniejsza część drewna pnia, przewodząca wodę.'),
 ('Dlaczego elementy drewna są martwe, a rurki sitowe żywe?', 'Przepływ wody (napędzany transpiracją) nie wymaga energii komórek, a puste wnętrze ułatwia przepływ; transport cukrów w łyku jest aktywny (załadunek wymaga ATP), więc rurki muszą być żywe.'),
 ('Wyjaśnij pojęcie: włoski (trichomy)', 'Wytwory skórki: ograniczają transpirację (odbijają światło, tworzą warstwę wilgotnego powietrza), chronią przed roślinożercami (włoski parzące pokrzywy), wydzielają substancje (gruczołowe).'),
 ('Funkcja miękiszu w łodydze', 'Wypełnia przestrzeń, magazynuje substancje i wodę, a w zielonych łodygach przeprowadza fotosyntezę.'),
 ('Wyjaśnij pojęcie: ryzoderma', 'Skórka korzenia — bez kutykuli i szparek, z włośnikami; przystosowana do pobierania wody.'),
 ('Dlaczego skórka liścia jest zwykle bezbarwna?', 'Komórki skórki (poza szparkowymi) nie mają chloroplastów — przepuszczają światło do miękiszu asymilacyjnego.'),
 ('Jak rozpoznać tkankę merystematyczną na preparacie?', 'Drobne, ściśle przylegające komórki z dużym jądrem, bez dużej wakuoli, często w różnych fazach podziału (np. stożek wzrostu korzenia cebuli).'),
], Q=[
 ('Przyrost łodygi na grubość u drzew zawdzięczamy:', ['merystemom wierzchołkowym', '*kambium i fellogenowi', 'merystemom interkalarnym', 'perycyklowi korzenia'], 'Merystemy boczne.'),
 ('Żywe komórki o nierównomiernie zgrubiałych celulozowych ścianach tworzą:', ['sklerenchymę', '*kolenchymę', 'drewno', 'korek'], 'Zwarcica.'),
 ('Sacharozę z liści do korzeni transportuje:', ['drewno', '*łyko', 'kolenchyma', 'korek'], 'Rurki sitowe.'),
 ('Naczynia różnią się od cewek tym, że:', ['są żywe', '*nie mają ścian poprzecznych', 'przewodzą cukry', 'występują u nagonasiennych'], 'Ciągłe rurki.'),
 ('Pasemka Caspary’ego występują w:', ['skórce liścia', '*endodermie korzenia', 'łyku', 'kambium'], 'Kontrola transportu do walca osiowego.'),
 ('Aerenchyma (miękisz powietrzny) jest typowa dla roślin:', ['pustynnych', '*wodnych i bagiennych', 'pasożytniczych', 'iglastych'], 'Dostęp tlenu.'),
 ('Wymianę gazową w korku umożliwiają:', ['szparki', '*przetchlinki', 'hydatody', 'włośniki'], 'Luźno ułożone komórki.'),
 ('Komórka przyrurkowa:', ['jest martwa i ma zdrewniałą ścianę', '*zawiera jądro i wspiera człon rurki sitowej', 'przewodzi wodę razem z naczyniami', 'występuje w drewnie wtórnym drzew'], 'Rurka sitowa nie ma jądra.'),
], pp='IX')

T['b-organy'] = dict(F=[
 ('Organy wegetatywne roślin', 'Korzeń, łodyga i liść — służą do odżywiania i wzrostu (a nie bezpośrednio do rozmnażania płciowego).'),
 ('Funkcje korzenia', 'Utrzymanie rośliny w podłożu, pobieranie wody i soli mineralnych, przewodzenie, magazynowanie substancji, synteza niektórych hormonów (cytokinin).'),
 ('Strefy korzenia (od wierzchołka)', 'Czapeczka, strefa merystematyczna (podziałów), strefa wydłużania, strefa włośnikowa (różnicowania), strefa korzeni bocznych.'),
 ('Funkcja czapeczki korzeniowej', 'Chroni merystem wierzchołkowy podczas wzrostu w glebie, wydziela śluz ułatwiający przesuwanie się, odbiera bodziec grawitacyjny (statolity).'),
 ('Budowa pierwotna korzenia (przekrój)', 'Ryzoderma z włośnikami, kora pierwotna (miękisz, endoderma), walec osiowy: perycykl, wiązka promienista — pasma drewna i łyka ułożone naprzemianlegle.'),
 ('Jak odróżnić na przekroju korzeń od łodygi? (matura 2026)', 'Korzeń — wiązka promienista, drewno i łyko naprzemianległe, endoderma i perycykl; łodyga — wiązki kolateralne (drewno i łyko naprzeciwlegle), często rdzeń.'),
 ('Budowa pierwotna łodygi rośliny dwuliściennej', 'Skórka, kora pierwotna, wiązki przewodzące kolateralne otwarte ułożone w pierścień, rdzeń.'),
 ('Budowa łodygi rośliny jednoliściennej', 'Wiązki kolateralne zamknięte (bez kambium) rozproszone w miękiszu; brak przyrostu wtórnego.'),
 ('Funkcje łodygi', 'Podtrzymanie liści i kwiatów (eksponowanie do światła), przewodzenie wody i asymilatów, magazynowanie, czasem fotosynteza i rozmnażanie wegetatywne.'),
 ('Budowa wtórna łodygi drzewa (od zewnątrz)', 'Korek (peryderma), kora (łyko wtórne), kambium, drewno wtórne (słoje), rdzeń.'),
 ('Wyjaśnij pojęcie: kora (w łodydze drzewa)', 'Wszystkie tkanki na zewnątrz kambium: łyko wtórne, kora pierwotna (resztki) i peryderma.'),
 ('Dlaczego obrączkowanie (zdjęcie pierścienia kory) zabija drzewo?', 'Przecina łyko — asymilaty z liści nie docierają do korzeni, które po wyczerpaniu zapasów obumierają (woda drewnem przepływa jeszcze przez jakiś czas).'),
 ('Budowa liścia (przekrój poprzeczny)', 'Skórka górna z kutykulą, miękisz palisadowy, miękisz gąbczasty z przestworami, wiązki przewodzące (nerwy), skórka dolna ze szparkami.'),
 ('Funkcje liścia', 'Fotosynteza, wymiana gazowa, transpiracja; czasem magazynowanie, ochrona, rozmnażanie.'),
 ('Związek budowy liścia z fotosyntezą', 'Duża, płaska blaszka (powierzchnia chwytania światła), miękisz palisadowy z chloroplastami pod skórką górną, przestwory i szparki dla CO₂, gęsta sieć wiązek dostarczających wodę i odprowadzających cukry.'),
 ('Liście światłolubne a cieniolubne', 'Światłolubne — grubsze, z wielowarstwowym miękiszem palisadowym, grubą kutykulą; cieniolubne — cieńsze, większe, z cienką kutykulą, więcej chlorofilu na chloroplast.'),
 ('Modyfikacje korzeni — przykłady', 'Spichrzowe (marchew, burak), czepne (bluszcz), podporowe (kukurydza), oddechowe (pneumatofory namorzyn), ssawki (jemioła, kanianka), powietrzne (storczyki epifityczne z welamenem), brodawki z bakteriami (bobowate).'),
 ('Modyfikacje łodygi — przykłady', 'Kłącza (perz, konwalia), bulwy (ziemniak), rozłogi (truskawka), cebule (tarczka łodygi), ciernie (głóg), wąsy (winorośl), łodygi spłaszczone — gałęziaki (opuncja), łodygi sukulentów.'),
 ('Modyfikacje liści — przykłady', 'Ciernie (kaktus, berberys), wąsy czepne (groch), liście spichrzowe (łuski cebuli, liście sukulentów), liście pułapkowe (rosiczka, dzbanecznik), łuski pąków, przylistki.'),
 ('Dlaczego ziemniak to zmodyfikowana łodyga, a nie korzeń?', 'Bulwa ma pąki (oczka) w kątach zredukowanych liści (blizny), wyrasta na podziemnych pędach (stolonach) i na świetle zielenieje — cechy łodygi.'),
 ('Dlaczego cierń kaktusa to zmodyfikowany liść?', 'Wyrasta z areoli w miejscu liścia; redukcja blaszki ogranicza transpirację, a fotosyntezę przejęła zgrubiała łodyga.'),
 ('Wyjaśnij pojęcie: sukulenty', 'Rośliny gromadzące wodę w miękiszu wodonośnym łodyg (kaktusy) lub liści (aloes, rozchodnik) — przystosowanie do suchych siedlisk.'),
 ('Przystosowania kserofitów', 'Gruba kutykula, mało szparek, szparki zagłębione, liście zwinięte lub zredukowane, włoski, głęboki lub rozległy system korzeniowy, miękisz wodonośny, fotosynteza CAM.'),
 ('Przystosowania hydrofitów', 'Aerenchyma, słabo rozwinięte tkanki wzmacniające i przewodzące, cienka kutykula, szparki po górnej stronie liści pływających, liście podwodne silnie podzielone.'),
 ('Przystosowania higrofitów', 'Cienka kutykula, duże, cienkie liście, liczne szparki, często hydatody, wzmożona transpiracja (np. włoski, brodawki zwiększające powierzchnię — matura 2026).'),
 ('Przystosowania roślin do zasiedlenia lądu (cechy budowy)', 'Skórka z kutykulą i szparkami, tkanki przewodzące z ligniną, tkanki wzmacniające, korzenie, nasiona i łagiewka pyłkowa.'),
 ('Dlaczego liście drzew strefy umiarkowanej opadają jesienią?', 'Zimą woda w glebie jest zamarznięta (susza fizjologiczna) — zrzucenie liści ogranicza utratę wody przez transpirację i uszkodzenia mrozem.'),
 ('Wyjaśnij pojęcie: ulistnienie', 'Sposób rozmieszczenia liści na łodydze: skrętoległe, naprzeciwległe, okółkowe — dobrze eksponuje liście do światła (mozaika liściowa).'),
 ('Wyjaśnij pojęcie: pąk', 'Zawiązek pędu (lub kwiatu) z merystemem wierzchołkowym okrytym łuskami — szczytowy lub boczny (w kątach liści).'),
 ('Wyjaśnij pojęcie: przyrost wtórny korzenia', 'Przyrost na grubość korzeni roślin dwuliściennych i nagonasiennych dzięki kambium i fellogenowi.'),
 ('Wyjaśnij pojęcie: brodawki korzeniowe', 'Zgrubienia korzeni (głównie bobowatych) z bakteriami brodawkowymi wiążącymi azot atmosferyczny.'),
 ('Wyjaśnij pojęcie: mikoryza', 'Symbioza korzeni roślin z grzybami — grzyb zwiększa pobieranie wody i soli (szczególnie fosforu), roślina dostarcza mu cukrów.'),
 ('Wyjaśnij pojęcie: welamen', 'Wielowarstwowa skórka korzeni powietrznych storczyków z martwych komórek chłonących wodę deszczową i parę wodną.'),
 ('Liście pułapkowe roślin owadożernych — znaczenie', 'Rośliny te rosną na glebach ubogich w azot (torfowiska) — trawiąc owady uzyskują związki azotu i fosforu.'),
 ('Dlaczego rośliny cieniolubne mają duże, cienkie liście?', 'Duża powierzchnia zwiększa ilość pochłanianego słabego światła, a cienka blaszka pozwala dotrzeć mu do wszystkich chloroplastów.'),
 ('Wyjaśnij pojęcie: łodyga zielna a zdrewniała', 'Zielna — miękka, krótkotrwała, z niewielką ilością drewna (rośliny zielne); zdrewniała — z dużą ilością drewna wtórnego (drzewa, krzewy).'),
 ('Funkcja rdzenia w łodydze', 'Magazynowanie substancji i wody (miękisz); u niektórych roślin zanika, tworząc pustą łodygę (np. źdźbło trawy).'),
 ('Dlaczego źdźbło trawy jest puste w środku, a mimo to wytrzymałe?', 'Konstrukcja rury z tkanką wzmacniającą na obwodzie i kolankami (węzłami) jest lekka i odporna na zginanie.'),
 ('Wyjaśnij pojęcie: gałęziaki', 'Spłaszczone, zielone pędy pełniące funkcję liści (np. opuncja, myszopłoch).'),
 ('Jak rozpoznać kłącze?', 'Podziemna łodyga rosnąca poziomo, z węzłami, łuskowatymi liśćmi i pąkami, z której wyrastają korzenie przybyszowe i nowe pędy.'),
], Q=[
 ('Wiązka promienista z naprzemianległym drewnem i łykiem jest cechą:', ['łodygi dwuliściennej', '*korzenia', 'liścia', 'łodygi jednoliściennej'], 'Matura 2026, zad. 7.1.'),
 ('Bulwa ziemniaka jest przekształconą:', ['korzeniem', '*łodygą', 'liściem', 'kwiatostanem'], 'Ma oczka (pąki).'),
 ('Miękisz palisadowy w liściu leży:', ['przy skórce dolnej', '*pod skórką górną', 'w nerwach', 'wokół szparek'], 'Najwięcej światła.'),
 ('Cierń kaktusa to przekształcony:', ['pęd', '*liść', 'korzeń', 'kwiat'], 'Ograniczenie transpiracji.'),
 ('Obrączkowanie pnia zabija drzewo, ponieważ przerywa:', ['drewno', '*łyko', 'rdzeń', 'twardziel'], 'Korzenie nie otrzymują cukrów.'),
 ('Wąsy grochu są przekształconymi:', ['przekształconymi łodygami', 'korzeniami przybyszowymi', '*fragmentami liścia złożonego', 'zredukowanymi kwiatami'], 'U grochu — części liścia złożonego.'),
], pp='IX')

T['b-gospodarka-wodna'] = dict(F=[
 ('Jak woda wnika do korzenia?', 'Przez włośniki — osmotycznie (komórki korzenia mają niższy potencjał wody niż roztwór glebowy), a następnie przez korę drogą apoplastyczną i symplastyczną do walca osiowego.'),
 ('Drogi transportu wody w korzeniu', 'Apoplastyczna (ścianami i przestworami — do endodermy), symplastyczna (przez cytoplazmę i plazmodesmy); w endodermie pasemka Caspary’ego wymuszają przejście przez symplast.'),
 ('Wyjaśnij pojęcie: parcie korzeniowe', 'Ciśnienie wytwarzane w korzeniu przez aktywne gromadzenie jonów w walcu osiowym (napływ wody osmotycznie) — wypycha wodę w górę (widoczne jako gutacja, „płacz” przyciętych roślin).'),
 ('Wyjaśnij pojęcie: siła ssąca liści', 'Spadek potencjału wody w liściach wskutek transpiracji, który „zasysa” wodę z drewna — główny mechanizm transportu wody w wysokich roślinach.'),
 ('Wyjaśnij pojęcie: teoria kohezyjno-adhezyjno-transpiracyjna', 'Woda jest wyciągana w górę naczyń przez transpirację (siła ssąca), a ciągłość słupa wody zapewnia kohezja cząsteczek wody i ich adhezja do ścian naczyń.'),
 ('Dlaczego transpiracja przyspiesza transport wody w drewnie? (matura 2026)', 'Parowanie wody z liści obniża potencjał wody w liściach, co dzięki kohezji przenosi się na cały słup wody w naczyniach — woda szybciej płynie z korzeni do liści.'),
 ('Wyjaśnij pojęcie: transpiracja', 'Parowanie wody z nadziemnych części rośliny, głównie przez szparki (transpiracja szparkowa) i w mniejszym stopniu przez kutykulę.'),
 ('Znaczenie transpiracji', 'Napędza transport wody i soli mineralnych w drewnie, chłodzi liście, umożliwia otwarte szparki do pobierania CO₂.'),
 ('Wyjaśnij pojęcie: transpiracja kutykularna', 'Parowanie wody przez kutykulę skórki — niewielka, zależna od grubości kutykuli; nie jest regulowana przez roślinę.'),
 ('Mechanizm otwierania szparek', 'Na świetle pompy protonowe w komórkach szparkowych aktywnie pobierają jony K⁺ (i Cl⁻, powstaje jabłczan) — spada potencjał osmotyczny i potencjał wody, woda napływa, turgor rośnie, a ze względu na nierównomierne zgrubienie ścian komórki wyginają się i szparka się otwiera.'),
 ('Mechanizm zamykania szparek', 'Przy niedoborze wody (sygnał — kwas abscysynowy) komórki szparkowe tracą jony K⁺, rośnie ich potencjał wody, woda wypływa, turgor spada i szparka się zamyka.'),
 ('Rola kwasu abscysynowego (ABA) w gospodarce wodnej', 'Hormon stresu — przy suszy wywołuje zamykanie szparek, ograniczając utratę wody.'),
 ('Wpływ temperatury na transpirację', 'Wyższa temperatura zwiększa parowanie (rośnie różnica prężności pary wodnej) — transpiracja rośnie, o ile szparki są otwarte.'),
 ('Wpływ światła na transpirację', 'Światło powoduje otwieranie szparek (i nagrzewa liście) — transpiracja rośnie.'),
 ('Wpływ wilgotności powietrza na transpirację', 'Im wyższa wilgotność, tym mniejsza różnica potencjału wody między liściem a powietrzem — transpiracja maleje.'),
 ('Wpływ wiatru na transpirację', 'Wiatr usuwa wilgotne powietrze znad liści — rośnie różnica stężeń pary wodnej i transpiracja (przy silnym wietrze szparki mogą się zamykać).'),
 ('Jak zmierzyć intensywność transpiracji?', 'Metodą wagową (ubytek masy rośliny w doniczce szczelnie owiniętej folią) lub potometrem (szybkość pobierania wody przez pęd).'),
 ('Wyjaśnij pojęcie: potometr', 'Przyrząd mierzący szybkość pobierania wody przez pęd rośliny (np. przesuw pęcherzyka powietrza w kapilarze) — pośrednio mierzy transpirację.'),
 ('Wyjaśnij pojęcie: bilans wodny rośliny', 'Różnica między ilością wody pobranej a wytranspirowanej; ujemny bilans prowadzi do więdnięcia.'),
 ('Wyjaśnij pojęcie: więdnięcie', 'Utrata turgoru przez komórki, gdy transpiracja przewyższa pobieranie wody — liście i młode pędy wiotczeją.'),
 ('Wyjaśnij pojęcie: susza fizjologiczna', 'Stan, w którym woda w podłożu jest obecna, ale niedostępna dla rośliny — np. przy zamarzniętej glebie lub dużym zasoleniu (roztwór glebowy hipertoniczny).'),
 ('Skutek suszy fizjologicznej dla bilansu wodnego', 'Roślina nie może pobrać wody, a nadal ją traci przez transpirację — bilans jest ujemny, roślina więdnie mimo wilgotnej gleby.'),
 ('Dlaczego rośliny na glebach zasolonych mają problem z wodą?', 'Zasolony roztwór glebowy ma niski potencjał wody — korzenie trudniej pobierają wodę, a nawet mogą ją tracić.'),
 ('Wyjaśnij pojęcie: halofity', 'Rośliny przystosowane do gleb zasolonych (np. soliród) — gromadzą sole w komórkach, by obniżyć potencjał wody, mają gruczoły solne.'),
 ('Wyjaśnij pojęcie: sole mineralne pobierane przez roślinę', 'Jony z roztworu glebowego (NO₃⁻, NH₄⁺, K⁺, PO₄³⁻, SO₄²⁻, Mg²⁺, Ca²⁺ i mikroelementy) — pobierane głównie aktywnie przez korzenie.'),
 ('Dostępne dla roślin formy azotu', 'Jony azotanowe (NO₃⁻) i amonowe (NH₄⁺); azotu atmosferycznego N₂ rośliny bezpośrednio nie wykorzystują (wyjątek — symbioza z bakteriami brodawkowymi).'),
 ('Dostępna dla roślin forma siarki', 'Jony siarczanowe (SO₄²⁻).'),
 ('Rola azotu w roślinie', 'Składnik aminokwasów, białek, kwasów nukleinowych, chlorofilu i ATP; niedobór — słaby wzrost i chloroza (żółknięcie od starszych liści).'),
 ('Rola siarki w roślinie', 'Składnik aminokwasów (cysteina, metionina) i niektórych koenzymów; niedobór — chloroza młodych liści.'),
 ('Rola magnezu w roślinie', 'Składnik chlorofilu, aktywator enzymów; niedobór — chloroza między nerwami starszych liści.'),
 ('Rola potasu w roślinie', 'Reguluje turgor i ruchy szparek, aktywuje enzymy, uczestniczy w transporcie asymilatów; niedobór — brązowienie brzegów liści, słaba odporność na suszę.'),
 ('Rola fosforu w roślinie', 'Składnik ATP, kwasów nukleinowych, fosfolipidów; niedobór — słaby rozwój korzeni, fioletowe zabarwienie liści.'),
 ('Dlaczego objawy niedoboru N, Mg, K pojawiają się najpierw na starszych liściach?', 'Te pierwiastki są ruchliwe w roślinie — przy niedoborze są przemieszczane ze starszych liści do młodszych, rosnących.'),
 ('Dlaczego objawy niedoboru wapnia i siarki pojawiają się na młodych liściach?', 'Te pierwiastki są mało ruchliwe w roślinie — nie mogą być przemieszczone ze starszych tkanek do nowo powstających.'),
 ('Wyjaśnij pojęcie: kultura wodna (hydroponika)', 'Hodowla roślin w roztworze soli mineralnych bez gleby — pozwala badać rolę poszczególnych pierwiastków (pomija się jeden i obserwuje objawy niedoboru).'),
 ('Jak zbadać znaczenie azotu dla rośliny?', 'Hodować rośliny w pełnej pożywce (kontrola) i w pożywce bez azotu, pozostałe warunki jednakowe; porównać wzrost i barwę liści.'),
 ('Wyjaśnij pojęcie: nawozy', 'Substancje dostarczające glebie składników mineralnych (N, P, K) — uzupełniają ubytki po zbiorach; nadmiar powoduje eutrofizację wód.'),
 ('Wyjaśnij pojęcie: transpiracja a pobieranie soli', 'Strumień transpiracyjny przenosi jony pobrane przez korzenie do pędów — przy słabej transpiracji dostawa soli do liści jest mniejsza.'),
 ('Dlaczego rośliny pustynne mają szparki zagłębione w skórce?', 'Nad zagłębioną szparką gromadzi się wilgotne powietrze — zmniejsza to różnicę wilgotności i transpirację.'),
 ('Dlaczego przesadzanie rośliny powoduje jej więdnięcie?', 'Uszkadzane są włośniki — pobieranie wody spada, a transpiracja trwa (bilans ujemny); dlatego przycina się część liści lub przesadza z bryłą ziemi.'),
 ('Wyjaśnij pojęcie: kawitacja (zator powietrzny)', 'Zerwanie słupa wody w naczyniu i powstanie pęcherzyka powietrza (np. przy silnej suszy, mrozie) — blokuje przepływ w tym naczyniu.'),
 ('Wyjaśnij pojęcie: potencjał wody a kierunek przepływu w roślinie', 'Woda płynie z gleby (najwyższy potencjał) przez korzeń i łodygę do liści i atmosfery (najniższy potencjał) — wzdłuż spadku potencjału.'),
 ('Jak gutacja różni się od transpiracji?', 'Gutacja — wydzielanie wody w postaci cieczy przez hydatody, napędzane parciem korzeniowym; transpiracja — parowanie wody (gaz) głównie przez szparki, napędzane różnicą wilgotności.'),
 ('Wyjaśnij pojęcie: komórki szparkowe — budowa', 'Fasolkowate (u traw hantlowate) komórki z chloroplastami i nierównomiernie zgrubiałymi ścianami (grubsza ściana od strony szparki) — przy wzroście turgoru wyginają się na zewnątrz.'),
 ('Dlaczego szparki znajdują się zwykle na spodniej stronie liścia?', 'Spodnia strona jest mniej nasłoneczniona i chłodniejsza — mniejsze straty wody przy otwartych szparkach.'),
], Q=[
 ('Główną siłą transportującą wodę w wysokich drzewach jest:', ['parcie korzeniowe', '*transpiracja (siła ssąca liści)', 'gutacja', 'transport aktywny w naczyniach'], 'Teoria kohezyjna.'),
 ('Otwieranie szparek następuje, gdy do komórek szparkowych:', ['wypływają jony K⁺', '*napływają jony K⁺ i woda', 'wnika CO₂', 'wnika ABA'], 'Wzrost turgoru.'),
 ('Transpiracja maleje, gdy:', ['rośnie temperatura', 'wieje wiatr', '*rośnie wilgotność powietrza', 'rośnie natężenie światła'], 'Mniejsza różnica wilgotności.'),
 ('Susza fizjologiczna występuje m.in., gdy:', ['gleba jest bardzo wilgotna', '*gleba jest zamarznięta lub silnie zasolona', 'wieje słaby wiatr', 'jest wysoka wilgotność powietrza'], 'Woda niedostępna.'),
 ('Dostępną dla roślin formą siarki jest:', ['siarka elementarna', 'H₂S', '*jon siarczanowy SO₄²⁻', 'SO₂ z powietrza'], 'Pobierana przez korzenie.'),
 ('Objawy niedoboru magnezu pojawiają się najpierw na liściach starszych, ponieważ magnez:', ['jest nieruchliwy', '*jest przemieszczany do młodszych liści', 'gromadzi się w korzeniach', 'jest pobierany tylko przez liście'], 'Pierwiastek ruchliwy.'),
 ('Pasemka Caspary’ego zmuszają wodę do przejścia przez:', ['ściany komórkowe (apoplast)', '*błony i cytoplazmę komórek endodermy', 'naczynia drewna pierwotnego', 'przestwory międzykomórkowe kory'], 'Kontrola selekcji jonów.'),
], pp='IX')
